            const C1 = BigInt(c1);
            const C2 = BigInt(c2);

            let best = null;

            for (let k = 1; k <= m; k++) {
                const K = BigInt(k);
                const base = N / K; // floor division
                const rem = N % K; // number of groups with size base+1

                // groups with size base+1: rem groups, contribute (base)^2 each (since size-1 = base)
                // groups with size base: (k-rem) groups, contribute (base-1)^2 each (since size-1 = base-1)
                const b1 = base; // (base+1 - 1) = base
                const b0 = base - 1n; // (base - 1)

                let sumSq = rem * (b1 * b1);
                if (K - rem > 0n) {
                    sumSq += (K - rem) * (b0 * b0);
                }

                const cost = K * C1 + C2 * sumSq;

                if (best === null || cost < best) {
                    best = cost;
                }
            }

            resolve(best.toString() + "\n");
