    let ptr = 0;
    const n = parseInt(tokens[ptr++], 10);
    const m = parseInt(tokens[ptr++], 10);

    const diff = new Int32Array(m + 2);

    for (let i = 0; i < n; i++) {
        const l = parseInt(tokens[ptr++], 10);
        const r = parseInt(tokens[ptr++], 10);
        diff[l] += 1;
        diff[r + 1] -= 1;
    }

    const cnt = new Int32Array(m);
    let running = 0;
    for (let x = 1; x <= m; x++) {
        running += diff[x];
        cnt[x - 1] = running;
    }

    // computeInc: for each i, length of longest non-decreasing subsequence ending at i
    function computeInc(arr) {
        const len = arr.length;
        const tails = new Int32Array(len);
        let tailsLen = 0;
        const res = new Int32Array(len);
        for (let i = 0; i < len; i++) {
            const x = arr[i];
            // find first index in tails[0..tailsLen-1] with tails[idx] > x
            let lo = 0, hi = tailsLen;
            while (lo < hi) {
                const mid = (lo + hi) >> 1;
                if (tails[mid] > x) {
                    hi = mid;
                } else {
                    lo = mid + 1;
                }
            }
            tails[lo] = x;
            if (lo === tailsLen) tailsLen++;
            res[i] = lo + 1;
        }
        return res;
    }

    const inc = computeInc(cnt);

    // reverse array
