    for (let i = 0; i < m; i++) {
        revArr[i] = cnt[m - 1 - i];
    }

    const decRaw = computeInc(revArr);

    const dec = new Int32Array(m);
    for (let i = 0; i < m; i++) {
        dec[i] = decRaw[m - 1 - i];
    }

    let answer = 0;
    for (let i = 0; i < m; i++) {
        const val = inc[i] + dec[i] - 1;
        if (val > answer) answer = val;
    }

    console.log(answer);
