process.stdin.resume();
process.stdin.setEncoding('utf8');

let inputData = '';
process.stdin.on('data', function(data) {
    inputData += data;
});

process.stdin.on('end', function() {
    const parts = inputData.trim().split(/\s+/).map(Number);
    const n = parts[0], x = parts[1], pos = parts[2];
    const MOD = 1000000007n;

    let lo = 0, hi = n - 1;
    let less = 0, greater = 0;
    while (lo < hi) {
        const mid = Math.floor((lo + hi) / 2);
        if (mid < pos) {
            less++;
            lo = mid + 1;
        } else if (mid > pos) {
            greater++;
            hi = mid;
        } else {
            hi = mid;
        }
    }

    function perm(a, b) {
        let result = 1n;
        for (let i = 0; i < b; i++) {
            result = (result * BigInt(a - i)) % MOD;
        }
        return result;
    }

    function factorial(k) {
        let result = 1n;
        for (let i = 2; i <= k; i++) {
            result = (result * BigInt(i)) % MOD;
        }
        return result;
    }

    const availableLess = x - 1;
    const availableGreater = n - x;

    let ans = 1n;
    ans = (ans * perm(availableLess, less)) % MOD;
    ans = (ans * perm(availableGreater, greater)) % MOD;

    const remaining = n - 1 - less - greater;
    ans = (ans * factorial(remaining)) % MOD;

    console.log(ans.toString());
});
