const fs = require('fs');

function main() {
    const input = fs.readFileSync('/dev/stdin', 'utf8').trim();
    const parts = input.split(/\s+/);
    let n = Number(parts[0]);
    let k = Number(parts[1]);

    const MOD = 1000000007n;

    function modpow(base, exp, mod) {
        base = base % mod;
        if (base < 0n) base += mod;
        let result = 1n;
        while (exp > 0n) {
            if (exp & 1n) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1n;
        }
        return result;
    }

    function factorize(num) {
        let factors = {};
        let m = num;
        for (let i = 2; i * i <= m; i++) {
            while (m % i === 0) {
                factors[i] = (factors[i] || 0) + 1;
                m = m / i;
            }
        }
        if (m > 1) {
            factors[m] = (factors[m] || 0) + 1;
        }
        return factors;
    }

    if (n === 1) {
        console.log("1");
        return;
    }

    const factors = factorize(n);

    let ans = 1n;

    for (const key in factors) {
        // key might be a string representation of a number (possibly large but within safe integer range)
        const p = Number(key);
        const e = factors[key];

        const pBig = BigInt(Math.round(p)) % MOD;

        // precompute inverses 1..e+1
        const inv = new Array(e + 2);
        for (let x = 1; x <= e + 1; x++) {
            inv[x] = modpow(BigInt(x), MOD - 2n, MOD);
        }

        // dp array
        let dp = new Array(e + 1).fill(0n);
        dp[e] = 1n;

        for (let step = 0; step < k; step++) {
            let newdp = new Array(e + 1).fill(0n);
            for (let j = 0; j <= e; j++) {
                if (dp[j] === 0n) continue;
                const contrib = (dp[j] * inv[j + 1]) % MOD;
                for (let i = 0; i <= j; i++) {
                    newdp[i] = (newdp[i] + contrib) % MOD;
                }
            }
            dp = newdp;
        }

        // compute expected value sum dp[i]*p^i
        let total = 0n;
        let pPow = 1n; // p^0
        for (let i = 0; i <= e; i++) {
            total = (total + dp[i] * pPow) % MOD;
            pPow = (pPow * pBig) % MOD;
        }

        ans = (ans * total) % MOD;
    }

    console.log(ans.toString());
}

main();
