    console.log(solve(n, t));
});

function solve(n, t) {
    // dp keyed by "y_dirPrev_h_v" -> count
    // dirPrev: -1 means no previous direction (only valid for i=1)
    // h = number of humps found so far, v = number of valleys found so far
    let dp = new Map();

    for (let y = 1; y <= 4; y++) {
        const key = `${y}_-1_0_0`;
        dp.set(key, (dp.get(key) || 0) + 1);
    }

    for (let i = 2; i <= n; i++) {
        const ndp = new Map();
        for (const [key, count] of dp) {
            const parts = key.split('_').map(Number);
            const y = parts[0], dirPrev = parts[1], h = parts[2], v = parts[3];

            for (let ny = 1; ny <= 4; ny++) {
                if (ny === y) continue; // no horizontal segments allowed
                const newDir = ny > y ? 1 : 0;
                let nh = h, nv = v;

                if (dirPrev !== -1) {
                    if (dirPrev === 1 && newDir === 0) {
                        nh++; // hump: up then down
                    } else if (dirPrev === 0 && newDir === 1) {
                        nv++; // valley: down then up
                    }
                }

                if (nh > t || nv > t - 1) continue; // prune invalid states early

                const nkey = `${ny}_${newDir}_${nh}_${nv}`;
                ndp.set(nkey, (ndp.get(nkey) || 0) + count);
            }
        }
        dp = ndp;
    }

    let total = 0;
    for (const [key, count] of dp) {
        const parts = key.split('_').map(Number);
        const h = parts[2], v = parts[3];
        if (h === t && v === t - 1) {
            total += count;
        }
    }

    return total;
}
